      int count = 0;
      int innerCount = 0;

      for (int k = 0; k < 8; k++) {
        int ni = i + k;
        int nj = j + k;

        if (ni < 0 || ni >= height || nj < 0 || nj >= width) {
          break;
        }

        if (rows[ni][nj] == 1) count++;

        int innerArea = cellSize * cellSize;
        if (ni == i && nj == j) {
          innerCount++;
        } else if (ni == i || nj == j) {
          innerCount++;
        }
      }

      double score = ((count * (innerCount + 1)) / innerArea) * (cellSize - k);

      dp[i] += score;

      if (innerCount >= 2) {
        for (int m = i + 1; m < height && m < i + 3; m++) {
          for (int n = j + 1; n < width && n < j + 3; n++) {
            int ni = m, nj = n;
            if (rows[ni][nj] == 1) {
              dp[i] += 1.0;
              break;
            }
          }
        }
      }

      visited[i][j] = true;
    }
  }

