      var d = file[step + 1];
      if (d == '/' || d == '\\' || d == '?' || d == '*' || d == ':') {
        continue;
      }
      if (c == '.' && d == 'm' && step + 2 < len && file[step + 2] == '3') {
        paused1 = true;
        continue;
      }
      if (c == '.' && d == 's' && step + 2 < len && file[step + 2] == '2') {
