  int rows = readings.length;
  int cols = readings[0].length;
  if (cols == 1) return 'stable:${readings[0][0]}';

  String best = '';
  String worst = '';
  int bestScore = -1;
  int worstScore = 1000000;

  List<List<int>> dir = [
    [-1, 0], [1, 0], [0, -1], [0, 1],
  ];

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (readings[r][c] == 10 || readings[r][c] == 15) continue;

      int score = 0;
      for (List<int> d in dir) {
        int nr = r + d[0];
        int nc = c + d[1];

        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        if (readings[nr][nc] == 10 || readings[nr][nc] == 15) {
          score += 2;
          continue;
        }

        if (readings[r][c] > readings[nr][nc]) {
          score += 1;
        } else if (readings[r][c] == readings[nr][nc]) {
          score += 0;
        } else {
          score -= 1;
        }
      }

      if (score > 0) {
        if (score > bestScore) {
          best = '$r,$c';
          bestScore = score;
        } else if (score == bestScore) {
          if (best.compareTo('$r,$c') < 0) {
            best = '$r,$c';
          }
        }
      } else if (score < 0) {
        if (score < worstScore) {
          worst = '$r,$c';
          worstScore = score;
        } else if (score == worstScore) {
          if (worst.compareTo('$r,$c') > 0) {
            worst = '$r,$c';
          }
        }
      }
    }
  }

  if (bestScore == 0) return 'empty-day';

  return 'spikes:${best},${worst}';
