List<int> fn0(List<int> initialSeats) {
  List<int> seats = List<int>.from(initialSeats);
  List<String> edits = [];
  List<int> undoStack = [];

  List<int> state() {
    return seats.reduce((a, b) => [a[0] + b[0], a[1] + b[1]]);
  }

  void commit() {
    if (edits.isEmpty) return;
    int status = state()[0];
    int cost = state()[1];
    for (String op in edits) {
      undoStack.add([op, status, cost]);
    }
    edits = [];
  }

  void rollback() {
    List<int> last = undoStack.removeLast();
    String op = last[0];
    int status = last[1];
    int cost = last[2];
    if (op == 'BEGIN') {
      seats = List<int>.from(last);
      edits = [];
    } else if (op == 'COMMIT') {
      commit();
    } else if (op == 'ROLLBACK') {
      for (int i = 0; i < seats.length; i++) {
        seats[i] = status;
      }
      edits = [];
    } else if (op.startsWith('INSERT ')) {
      int seat = int.parse(op.substring(7));
      if (status[2] >= seat) {
        seats.add([seat, status[3]]);
      }
    } else if (op.startsWith('DELETE ')) {
      int seat = int.parse(op.substring(7));
      if (status[2] >= seat) {
        int idx = seats.indexOf([seat, status[3]]);
        if (idx != -1) seats.removeAt(idx);
      }
    } else if (op == 'BEGIN') {
      edits.add(op);
    } else if (op == 'COMMIT') {
      commit();
    } else if (op == 'ROLLBACK') {
      rollback();
    } else {
      print('Invalid edit: $op');
    }
  }

  for (String cmd in ['BEGIN', 'COMMIT', 'ROLLBACK'] + ['INSERT ', 'DELETE '].map((s) => s + '12')) {
    edits.add(cmd);
  }
  commit();
  return seats;
}

