bool fn0(String script, int maxUndoPenalty) {
  List<int> stack = [];
  for (int i = 0; i < script.length; i++) {
    String ch = script[i];
    if (ch == '(') {
      stack.add(0);
    } else if (ch == '[') {
      stack.add(0);
    } else if (ch == ')' || ch == ']') {
      if (stack.isEmpty) return false;
      int parent = stack.removeLast();
      if (ch == ')') {
        if (parent < 0) return false;
      } else if (ch == ']') {
        if (parent > 0) return false;
      }
    } else if (ch == 'UNDO') {
      if (stack.isEmpty) return false;
      stack.removeLast();
    } else if (ch == '!') {
      if (stack.length < 2) return false;
      int a = stack.removeLast();
      int b = stack.removeLast();
      stack.add(a + b);
    } else if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
      if (stack.length < 1) return false;
      stack[0] += ch.codeUnitAt(0) - 64;
    } else {
      return false;
    }
  }
  return stack.isEmpty && maxUndoPenalty == 0;
}

