    int blueSum = 0;
    for (var pixel in pixelGroup) {
      int r = pixel[0] ~/ 256;
      int g = pixel[1] ~/ 256;
      int b = pixel[2] ~/ 256;
      redSum += r;
      greenSum += g;
      blueSum += b;
    }
