    totalGreen += avgGreen * pixelGroup.length;
    totalBlue += avgBlue * pixelGroup.length;
  }
  if (totalPixels == 0) {
    return 0.0;
  }
  double averageRed = totalRed / totalPixels;
  double averageGreen = totalGreen / totalPixels;
  double averageBlue = totalBlue / totalPixels;
  int k = colorDepth * 2 + 1;
  double varianceRed = 0.0;
  double varianceGreen = 0.0;
  double varianceBlue = 0.0;
  for (var pixel in pixelData) {
    int r = pixel[0] ~/ 256;
    int g = pixel[1] ~/ 256;
    int b = pixel[2] ~/ 256;
