    varianceGreen += (g - averageGreen) * (g - averageGreen);
    varianceBlue += (b - averageBlue) * (b - averageBlue);
  }
  double stdDevRed = varianceRed > 0 ? varianceRed / totalPixels : 0.0;
  double stdDevGreen = varianceGreen > 0 ? varianceGreen / totalPixels : 0.0;
  double stdDevBlue = varianceBlue > 0 ? varianceBlue / totalPixels : 0.0;
